        ]
      },
      {
        "description": "Binary indicator for whether the hurricane name is female (1) or male (0).",
        "columns": [
          "female_name"
        ]
      }
    ],
    "dv": {
      "description": "Observed total fatalities caused by the hurricane (used as a proxy for the public taking fewer precautionary measures). This is a count variable and will be modeled with a count model (negative binomial) to account for overdispersion.",
      "columns": [
        "Deaths"
      ]
    },
    "controls": [
      {
        "description": "Maximum sustained wind speed at landfall (mph). Controls for hurricane intensity.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "wind_c"
        ]
      },
      {
        "description": "Saffir-Simpson category of the hurricane at landfall (1-5). Controls for storm intensity.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "category_c"
        ]
      },
      {
        "description": "Minimum central pressure at landfall (hPa). Lower values indicate stronger storms. Included as an additional intensity control (centered).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "min_c"
        ]
      },
      {
        "description": "Year of occurrence, centered to control for temporal trends in warning systems, evacuation behavior, and reporting.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "year_c"
        ]
      },
      {
        "description": "Elapsed years since the hurricane (as provided). Included as an additional temporal control (keeps original scale).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
